sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float zoom;
uniform float chromatic;
uniform float vignette;
uniform float transparentEdge;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 hs = size * 0.5;
    float2 ctr = center * size;
    float2 d = (coord - ctr) / hs;
    float r2 = dot(d, d);
    float sr = strength * (1.0 + chromatic * 0.15);
    float sb = strength * (1.0 - chromatic * 0.15);
    float2 pr = ctr + d * (1.0 + sr * r2) * hs / zoom;
    float2 pg = ctr + d * (1.0 + strength * r2) * hs / zoom;
    float2 pb = ctr + d * (1.0 + sb * r2) * hs / zoom;
    float4 cr = transparentEdge > 0.5 ? texT(pr) : tex(pr);
    float4 cg = transparentEdge > 0.5 ? texT(pg) : tex(pg);
    float4 cb = transparentEdge > 0.5 ? texT(pb) : tex(pb);
    float4 r = float4(cr.r, cg.g, cb.b, cg.a);
    r = float4(r.rgb * (1.0 - vignette * r2 * 0.5), r.a);
    return fin(c, r, opacity);
}
